"""Throwaway deterministic native demo benchmark, not live-feed throughput proof."""
import asyncio
from dataclasses import fields, is_dataclass
from decimal import Decimal
from hashlib import sha256
import json
from pathlib import Path
import statistics
import sys
import time

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from src.workstation import runtime as module
from src.workstation.precision import DERIVED_DECIMAL_POLICY, canonical_decimal


def baseline(value):
    if value is None or isinstance(value, (str, bool)):
        return value
    if isinstance(value, Decimal):
        return canonical_decimal(value, policy=DERIVED_DECIMAL_POLICY)
    if isinstance(value, int):
        return str(value)
    if isinstance(value, float):
        return value
    if is_dataclass(value):
        return {field.name: baseline(getattr(value, field.name)) for field in fields(value)}
    if isinstance(value, dict):
        return {str(key): baseline(item) for key, item in value.items()}
    if isinstance(value, (tuple, list, set, frozenset)):
        return [baseline(item) for item in value]
    raise TypeError(f"unsupported terminal DTO: {type(value).__name__}")


def containers(value, seen=None):
    seen = set() if seen is None else seen
    if isinstance(value, (dict, list)) and id(value) not in seen:
        seen.add(id(value))
        for item in value.values() if isinstance(value, dict) else value:
            containers(item, seen)
    return len(seen)


async def main():
    runtime = module.TerminalRuntime()
    try:
        await runtime.start()
        session = await runtime.create()

        def measure():
            session.replay.seek_delivery(session.replay.total_deliveries)
            snapshot = session.engine.snapshot(session.instrument_id, session.replay.clock.reading, key=session.key)
            changed = module.dto
            timings = {"before": [], "after": []}
            outputs = {}
            try:
                for index in range(50):
                    choices = [("before", baseline), ("after", changed)]
                    if index % 2:
                        choices.reverse()
                    for name, convert in choices:
                        module.dto = convert
                        started = time.thread_time_ns()
                        output = module._analytics_presentation(snapshot)
                        timings[name].append((time.thread_time_ns() - started) / 1_000_000)
                        encoded = json.dumps(output, sort_keys=True, separators=(",", ":")).encode()
                        outputs[name] = {"sha256": sha256(encoded).hexdigest(), "encoded_bytes": len(encoded), "unique_containers": containers(output)}
                assert outputs["before"]["sha256"] == outputs["after"]["sha256"]
                return {"source": "Repository's explicit synthetic demo, complete native replay prefix; not live venue data or a throughput guarantee.",
                        "delivery_count": session.replay.total_deliveries,
                        "metrics": len(snapshot.metrics),
                        "outputs": outputs,
                        "timing": {name: {"iterations": len(values), "median_cpu_ms": statistics.median(values), "p95_cpu_ms": sorted(values)[47], "max_cpu_ms": max(values)} for name, values in timings.items()}}
            finally:
                module.dto = changed

        report = await session.work(measure)
        report["harness_source"] = Path(__file__).read_text()
        Path(sys.argv[1]).write_text(json.dumps(report, indent=2) + "\n")
        print(json.dumps({key: value for key, value in report.items() if key != "harness_source"}, indent=2))
    finally:
        await runtime.close()


asyncio.run(main())
